const U = 72000;
const D = 7;
const b = $json.body;

function clasificar(b) {
  // Regla 2 - DATOS_INVALIDOS
  if (b.id_solicitud == null || b.id_solicitud === "")
    return { ruta: "DATOS_INVALIDOS", motivo: "INVALIDO_CAMPO" };
  const monto = Number(b.monto);
  const dias  = Number(b.dias_desde_compra);
  if (!(monto > 0))
    return { ruta: "DATOS_INVALIDOS", motivo: "INVALIDO_MONTO" };
  // Regla 3 - RECHAZO (plazo antes que estado)
  if (dias > D)
    return { ruta: "RECHAZO", motivo: "RECHAZO_PLAZO" };
  if (b.estado_producto === "danado_por_uso")
    return { ruta: "RECHAZO", motivo: "RECHAZO_ESTADO" };
  // Regla 4 - REVISION (monto antes que falla)
  if (monto > U)
    return { ruta: "REVISION", motivo: "REVISION_MONTO" };
  if (b.estado_producto === "con_fallas")
    return { ruta: "REVISION", motivo: "REVISION_FALLA" };
  // Regla 5 - APROBACION (fallback)
  return { ruta: "APROBACION", motivo: "APROBACION" };
}

const r = clasificar(b);
return [{ json: {
  id_solicitud: b.id_solicitud,
  sku: b.sku,
  monto: Number(b.monto),
  dias_desde_compra: Number(b.dias_desde_compra),
  estado_producto: b.estado_producto,
  ruta: r.ruta,
  motivo: r.motivo,
  U, D
} }];
